#nullable enable // autogenerated

namespace MVZ2
{
    public static class StringHelper
    {
        public static string GetLastLines(this string text, int lineCount)
        {
            if (string.IsNullOrEmpty(text) || lineCount <= 0)
                return string.Empty;

            int end = text.Length;

            // 只用于定位“有效最后一行”的末尾，不用于最终截断
            while (end > 0 && (text[end - 1] == '\n' || text[end - 1] == '\r'))
                end--;

            if (end == 0)
                return text; // 全是换行符时，按原样返回；也可按你的定义返回 string.Empty

            int newlineCount = 0;
            int i = end - 1;

            for (; i >= 0; i--)
            {
                if (text[i] == '\n')
                {
                    newlineCount++;
                    if (newlineCount == lineCount)
                    {
                        i++; // 跳到这一行开头
                        break;
                    }
                }
            }

            if (i < 0)
                return text; // 行数不足，原样返回，保留换行
            return text.Substring(i);
        }
    }
}
